{
  "table": "crm_contacts",
  "columns": [
    {
      "target": "contact_id",
      "source": ["id"],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Maps directly to contact_id"
    },
    {
      "target": "full_name",
      "source": ["name.first", "name.last"],
      "transform": "concat",
      "params": {},
      "confidence": 1.0,
      "note": "Combines first and last name into 'First Last'"
    },
    {
      "target": "email",
      "source": ["contact.email"],
      "transform": "text",
      "params": {
        "case": "lower"
      },
      "confidence": 1.0,
      "note": "Maps email address in lower case"
    },
    {
      "target": "phone",
      "source": ["contact.phone"],
      "transform": "phone_e164",
      "params": {
        "country": "64"
      },
      "confidence": 1.0,
      "note": "Standardises phone number to E.164 with NZ default country code"
    },
    {
      "target": "company",
      "source": ["org.name"],
      "transform": "text",
      "params": {},
      "confidence": 1.0,
      "note": "Maps company organization name"
    },
    {
      "target": "created_on",
      "source": ["created_at"],
      "transform": "date_from_datetime",
      "params": {
        "format": "%Y-%m-%dT%H:%M:%SZ"
      },
      "confidence": 1.0,
      "note": "Extracts date from ISO datetime"
    },
    {
      "target": "lifetime_value",
      "source": ["stats.ltv"],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Maps customer lifetime value in NZD"
    }
  ],
  "ignore": {
    "stats.orders": "No matching column in crm_contacts for total order count."
  },
  "review": []
}
